import socket
def send_request(sock,parts):
    previous=sock.getsockopt(socket.IPPROTO_TCP,socket.TCP_NODELAY)
    total=0
    try:
        sock.setsockopt(socket.IPPROTO_TCP,socket.TCP_NODELAY,1)
        for part in parts:
            if not isinstance(part,bytes) or not part: raise ValueError("nonempty byte fragments required")
            if total+len(part)>65536: raise ValueError("request budget exceeded")
            sock.sendall(part)
            total+=len(part)
        if not total: raise ValueError("empty request")
        return total
    finally:
        sock.setsockopt(socket.IPPROTO_TCP,socket.TCP_NODELAY,previous)
```

